-- Add the remaining 25 coding ai posts with proper type casting
INSERT INTO public.social_media_posts (day, title, description, theme, category, user_id, status) 
SELECT 
  s.day,
  s.title,
  s.description,
  s.theme,
  s.category,
  (SELECT DISTINCT user_id FROM social_media_posts LIMIT 1) as user_id,
  s.status::post_status
FROM (VALUES
  (6, 'A Prompt for Every Code', 'Imagine an AI "codec" that knows every medical code by prompt. In the near future, clinicians or coders might simply describe the procedure or diagnosis in natural language, and an AI agent will return the exact CPT code or ICD-10 code – effectively one perfect prompt for every billable item.', 'autonomous coding', 'coding ai', 'draft'),
  (7, 'LLMs Beat Human Coders Now', 'The AI revolution in coding has arrived thanks to large language models (LLMs). Before advanced LLMs, coding automation tech often fell short of human accuracy. But post-GPT advancements, AI models are now matching – even beating – human coders in accuracy and speed.', 'autonomous coding', 'coding ai', 'draft'),
  (8, 'AI Improves Coding Accuracy', 'Medical coding is prone to human error, from typos to missed codes, but AI is dramatically improving accuracy. Cutting-edge autonomous coding engines have demonstrated over 95% accuracy in assigning codes, outperforming typical manual coding benchmarks.', 'autonomous coding', 'coding ai', 'draft'),
  (9, '5x Faster Coding Throughput', 'AI isn''t just a little faster at coding – it''s orders of magnitude faster. One AI-powered solution achieved a 5–7× productivity boost in coding tasks. What a human coder might do in an hour, AI can potentially do in minutes or seconds.', 'autonomous coding', 'coding ai', 'draft'),
  (10, 'Big Savings for CFOs and Investors', 'The financial impact of AI-driven coding automation is enormous. By slashing labor costs and increasing accuracy, AI can cut coding-related costs by up to 35% for providers. Fewer errors also mean fewer denied claims.', 'autonomous coding', 'coding ai', 'draft'),
  (11, 'Slash Denials, Boost Revenue', 'AI-based coding doesn''t just save money on labor; it can increase revenue by coding more completely and correctly. Hospitals using autonomous coding engines have seen claims denial rates drop by up to 50%.', 'autonomous coding', 'coding ai', 'draft'),
  (12, 'Faster Cash Flow with AI Coding', 'AI coding significantly speeds up reimbursement cycles. By automating coding, organizations have cut 5+ days off their Accounts Receivable (A/R) times on average. The result is not only more revenue captured, but also more reliable data.', 'autonomous coding', 'coding ai', 'draft'),
  (13, 'Built-In Compliance, Always On', 'AI coding systems are being built with compliance and auditability at their core. Every code an AI assigns can be linked back to the source documentation and the algorithm''s reasoning, creating an audit trail far more detailed than a human''s.', 'autonomous coding', 'coding ai', 'draft'),
  (14, 'Less Paperwork, More Patient Time', 'By offloading routine coding to machines, healthcare professionals – from doctors to human coders – can refocus on what matters most: patient care. Even professional coders benefit, as their role shifts from mind-numbing data entry to supervising AI outputs.', 'autonomous coding', 'coding ai', 'draft'),
  (15, 'Inpatient + Outpatient = One Engine', 'AI coding tools are versatile and can bridge the gap between inpatient and outpatient coding. This means a single AI platform could handle coding for a patient''s entire journey, ensuring uniform standards.', 'autonomous coding', 'coding ai', 'draft'),
  (16, 'Investors Back the Future of Coding', 'Venture capital is pouring into AI-driven coding startups, signaling strong confidence in this transformation. In 2024–2025, funding for AI health companies has surged – with autonomous coding platforms raising significant rounds.', 'autonomous coding', 'coding ai', 'draft'),
  (17, 'Meet the AI Coding Pioneers', 'A new cohort of startups is leading the charge to make autonomous coding a reality. Companies like Nym Health, Fathom, and AKASA are deploying at scale, creating an arms race of innovation.', 'autonomous coding', 'coding ai', 'draft'),
  (18, '200,000 Coders = Opportunity', 'In the U.S., over 200,000 medical coders still manually process charts. This has become a bottleneck in healthcare operations, with frequent backlogs and errors. Investors see a classic disruption scenario.', 'autonomous coding', 'coding ai', 'draft'),
  (19, 'AI in Epic and Everywhere Else', 'Health systems are beginning to embrace AI coding solutions, integrating them with electronic health records. Epic now has a category for Fully Autonomous Coding tools.', 'autonomous coding', 'coding ai', 'draft'),
  (20, 'Yes, Insurers Will Accept It', 'A key stakeholder in the coding revolution is the payer. The good news: payers are chiefly concerned with accuracy and compliance, and AI is delivering on those fronts.', 'autonomous coding', 'coding ai', 'draft'),
  (21, 'Solving the Talent Shortage', 'The coding profession has been facing a 30% talent shortage nationwide. AI presents a solution: acting as a force multiplier for the existing workforce.', 'autonomous coding', 'coding ai', 'draft'),
  (22, 'Coders Become AI Auditors', 'Rather than making human coders obsolete, AI is changing their roles. Think ''coder 2.0'': professionals who oversee AI outputs, handle complex cases, and continually train/improve the AI models.', 'autonomous coding', 'coding ai', 'draft'),
  (23, 'Tackling Privacy and Trust Issues', 'For AI coding, a major concern is data privacy and security. These AI systems must handle sensitive patient information, so they need robust safeguards to prevent breaches.', 'autonomous coding', 'coding ai', 'draft'),
  (24, 'Regulators Are Catching Up', 'U.S. regulators and industry bodies are beginning to acknowledge and guide the use of AI in administrative healthcare tasks. The policy environment is gradually aligning to support AI innovations.', 'autonomous coding', 'coding ai', 'draft'),
  (25, 'Training the Coders of the Future', 'Training an AI coder involves feeding it vast numbers of clinical notes and their correct codes, so it learns the patterns. Fortunately, years of electronic health records provide a rich training ground.', 'autonomous coding', 'coding ai', 'draft'),
  (26, 'AI Owns Radiology. Next: Everything', 'One of the first domains to see AI coding success is radiology. But it doesn''t stop there – specialties like emergency medicine, surgery, and even complex inpatient cases are on the AI radar.', 'autonomous coding', 'coding ai', 'draft'),
  (27, 'Beyond Coding: Full RCM Automation', 'Autonomous coding is a cornerstone, but it''s part of a larger trend of AI optimizing the entire revenue cycle management (RCM). The end game is a largely self-driving revenue cycle.', 'autonomous coding', 'coding ai', 'draft'),
  (28, '5 Years to Full AI Adoption', 'Change is coming fast. Many hospitals are already in pilot phases or partial deployments. Within 5 years, a majority of U.S. health systems will have autonomous or AI-augmented coding.', 'autonomous coding', 'coding ai', 'draft'),
  (29, 'Destroying Administrative Waste', 'The shift to AI coding is part of a broader vision to eliminate wasteful administrative overhead in healthcare. Roughly a quarter of U.S. healthcare spending goes to admin functions.', 'autonomous coding', 'coding ai', 'draft'),
  (30, 'Lead the Revolution Now', 'We conclude the 30-day journey with a call to action: embrace AI-driven coding. The vision of "a single prompt for every code" is not science fiction; it''s an emerging reality.', 'autonomous coding', 'coding ai', 'draft')
) as s(day, title, description, theme, category, status);